<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#ADBAC7;">    answer </span><span style="--shiki-light:#A0111F;--shiki-dark:#F47067;">=</span><span style="--shiki-light:#0E1116;--shiki-dark:#ADBAC7;"> GoMeta</span><span style="--shiki-light:#A0111F;--shiki-dark:#F47067;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#6CB6FF;">evaluatedAltValue</span><span style="--shiki-light:#0E1116;--shiki-dark:#ADBAC7;">(delivery, block, </span><span style="--shiki-light:#023B95;--shiki-dark:#6CB6FF;">:Visib</span><span style="--shiki-light:#0E1116;--shiki-dark:#ADBAC7;">)   </span><span style="--shiki-light:#4B535D;--shiki-dark:#768390;"># the Engine&#39;s answer for this Block</span></span>
